const dir=path.join(__dirname,'../dist');
function harness(saved,options={}){const elements=new Map(),listeners={},local=new Map();if(saved)local.set("engefex-gerenciamento-v1",JSON.stringify(saved));function el(sel){if(!elements.has(sel))elements.set(sel,{innerHTML:'',textContent:'',value:'',style:{},open:false,files:[],options:[],selectedOptions:[],classList:{toggle(){},remove(){}},querySelectorAll:()=>[],addEventListener(n,fn){this[n]=fn},showModal(){this.open=true},close(){this.open=false},focus(){},setSelectionRange(){},click(){}});return elements.get(sel)}let context={EngefexCloud:options.cloud,console,Date,Intl,Map,Set,Math,Number,JSON,Object,Array,String,RegExp,Error,URL,Blob,URLSearchParams,clearTimeout,setTimeout:()=>1,confirm:()=>true,location:{hash:''},localStorage:{getItem:k=>local.get(k)||null,setItem:(k,v)=>{if(options.quota?.(k,v)){let e=new Error("The quota has been exceeded.");e.name="QuotaExceededError";throw e}local.set(k,v)}},document:{body:{classList:{toggle(){},remove(){},add(){}}},getElementById:()=>null,querySelector:sel=>['#search','#filter','#dayDate','#weekDate','#field-project'].includes(sel)?null:el(sel),querySelectorAll:()=>[],addEventListener:(n,f,capture)=>{if(!capture)listeners[n]=f},createElement:()=>({click(){}})}};context.window=context;context.addEventListener=(n,fn)=>listeners['window:'+n]=fn;context.scrollTo=()=>{};context.print=()=>{};context.open=()=>{};vm.createContext(context);for(let name of ['currency.js','data.js','domain.js','budget-type2.js','manager.js','diary-adapter.js','schedule-import.js','grid.js','records-grid.js','suppliers.js','purchases.js','measurement-forecast.js','payables.js','mobile.js','measurement-sheet.js','retentions.js','labor-contracts.js','financial-removal.js','fixed-expenses.js','receivable-filters.js','receivable-installments.js','factory-template.js','factory-model.js','factory-flow.js','factory.js','app.js']){if(name==='app.js'&&options.access){vm.runInContext(fs.readFileSync(path.join(dir,'access.js'),'utf8'),context);context.EngefexAccess.setContext(options.access)}vm.runInContext(fs.readFileSync(path.join(dir,name),'utf8'),context,{filename:name})}return {context,el,local,emit:(name,event)=>listeners['window:'+name]?.(event),click:dataset=>listeners.click({target:{closest:()=>({dataset})}}),route(name){context.location.hash='#'+name;listeners['window:hashchange']()}}}
test('todas as telas originais e Obras abrem com base vazia',()=>{let h=harness();assert.match(h.el('#main').innerHTML,/primeira obra/);for(let route of ['projects','dashboard','agenda','activities','timeline','budget','supplies','measurements','checklist','issues','diary','documents','teams']){h.route(route);assert.match(h.el('#main').innerHTML,/<h1>/,route);assert.doesNotMatch(h.el('#main').innerHTML,/undefined|NaN/,route)}assert.match(h.el('#nav').innerHTML,/Agenda do engenheiro/);assert.match(h.el('#nav').innerHTML,/Equipes e produtividade/)});
test('formulário de obra permite editar nome, valor e prazos',()=>{let h=harness();h.click({action:'new:projects'});assert.equal(h.el('#editor').open,true);for(let field of ['name','value','referenceDays','start','owner'])assert.match(h.el('#fields').innerHTML,new RegExp('name="'+field+'"'));});

test('telas e subabas preservam renderização com dados migrados',()=>{let data={version:1,projects:[{id:'p',name:'Obra cadastrada',amount:500}],stages:[{id:'e',project:'p',name:'Etapa',code:'1'}],services:[{id:'a',project:'p',stage:'e',name:'Serviço',unit:'m²',quantity:10,total:100,executed:2}],quotes:[{id:'q',project:'p',stage:'e',name:'Cotação',supplier:'Fornecedor',amount:50}],diary:[{id:'d',project:'p',date:'2026-10-16',description:'Executado',attachments:[]}],materials:[{id:'m',project:'p',name:'Insumo',activity:'a',unit:'kg',needed:10,initial:2,ordered:0}]};let h=harness(data);for(let route of ['projects','dashboard','agenda','activities','timeline','budget','supplies','measurements','checklist','issues','diary','documents','teams']){h.route(route);assert.match(h.el('#main').innerHTML,/<h1>/,route);assert.doesNotMatch(h.el('#main').innerHTML,/undefined|NaN/,route)}for(let [route,tab,values]of [['budget','budget',['quotes','costs','stages']],['documents','documents',['files','history','diagnosis']],['agenda','agenda',['week','all','day']],['supplies','supplies',['moves','materials']]]){h.route(route);for(let value of values){h.click({tab,value});assert.doesNotMatch(h.el('#main').innerHTML,/undefined|NaN/,route+' '+value)}}});

test('códigos curtos persistem sem alterar IDs e aparecem nos seletores',()=>{const original='projects-mvc2u3g4-o6sua';let h=harness({version:1,projects:[{id:original,name:'Ampliação PA'},{id:'outra',code:'OB-001',name:'Plataforma UTA'}]});let saved=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(saved.projects[0].id,original);assert.equal(saved.projects[0].code,'OB-002');assert.equal(saved.projects[1].code,'OB-001');assert.match(h.el('#project').innerHTML,/value="projects-mvc2u3g4-o6sua">OB-002 · Ampliação PA/);h.route('projects');assert.match(h.el('#main').innerHTML,/<small>OB-002<\/small>/);assert.doesNotMatch(h.el('#main').innerHTML,new RegExp('<small>'+original));h.click({action:'new:projects'});assert.match(h.el('#fields').innerHTML,/name="code"[^>]*value="OB-003"/);let normalized=h.context.EngefexManager.ensureProjectCodes(saved);assert.equal(normalized.projects[0].code,'OB-002');assert.equal(saved.projects[0].id,original);});


