test('confirmar cronograma grava dados e abre Etapas e atividades já atualizada',async()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra',amount:500}],stages:[{id:'e',project:'p',name:'Etapa',code:'1'}],services:[{id:'a',project:'p',stage:'e',name:'Serviço existente',unit:'m²',quantity:10,total:500,executed:2}]});let saved=JSON.parse(h.local.get('engefex-gerenciamento-v2')),result={errors:[],rows:[{sourceId:'1',wbs:'1',name:'Etapa',summary:true,parent:'',importKey:'etapa|1',start:'2026-10-19',finish:'2026-10-20',durationOriginal:'2 dias'},{sourceId:'2',wbs:'1.1',name:'Serviço existente',summary:false,parent:'1',importKey:'etapa|1.1',start:'2026-10-19',finish:'2026-10-20',durationOriginal:'2 dias',completed:50,planned:50,predecessors:[]},{sourceId:'3',wbs:'1.2',name:'Atividade nova do PDF',summary:false,parent:'1',importKey:'etapa|1.2',start:'2026-10-21',finish:'2026-10-22',durationOriginal:'2 dias',completed:0,planned:0,predecessors:['2']}]};await h.context.EngefexScheduleImport.commit('p',result,{'2':'a','3':'new'},'teste.pdf',saved);assert.equal(h.context.location.hash,'#activities');assert.match(h.el('#main').innerHTML,/Cronograma aplicado: 1 atividades criadas e 1 atualizadas/);assert.match(h.el('#main').innerHTML,/Atividade nova do PDF/);assert.match(h.el('#main').innerHTML,/19\/10\/2026/);let current=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(current.activities.length,2);assert.equal(current.stages.length,1);assert.equal(current.budgetItems.find(a=>a.id==='a').sale,500);assert.equal(current.activities.find(a=>a.id==='a').executed,2);h.route('timeline');assert.match(h.el('#main').innerHTML,/Atividade nova do PDF/);h.route('activities');assert.match(h.el('#main').innerHTML,/Atividade nova do PDF/)});

test('alterações de outra aba aparecem automaticamente e respeitam formulário aberto',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa'}],services:[{id:'a',project:'p',stage:'e',name:'Antes',quantity:1,total:0}]});h.route('activities');let s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));s.activities[0].name='Atualizado em outra aba';h.local.set('engefex-gerenciamento-v2',JSON.stringify(s));h.emit('storage',{key:'engefex-gerenciamento-v2'});assert.match(h.el('#main').innerHTML,/Atualizado em outra aba/);h.el('#editor').open=true;s.activities[0].name='Atualização adiada';h.local.set('engefex-gerenciamento-v2',JSON.stringify(s));h.emit('focus');assert.doesNotMatch(h.el('#main').innerHTML,/Atualização adiada/);h.el('#editor').open=false;h.emit('focus');assert.match(h.el('#main').innerHTML,/Atualização adiada/)});

test('Orçamento tem aba própria e telas, seletores e formulários separados do cronograma',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa original'}],services:[{id:'a',project:'p',stage:'e',name:'Original',unit:'m³',quantity:10,total:1000}]});let s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));s.budgetItems[0].name='Item financeiro exclusivo';s.activities[0].name='Atividade de planejamento exclusiva';s.budgetStages[0].name='Etapa financeira';s.stages[0].name='Etapa de planejamento';h.local.set('engefex-gerenciamento-v2',JSON.stringify(s));h.emit('storage',{key:'engefex-gerenciamento-v2'});h.route('budget');assert.match(h.el('#nav').innerHTML,/>Orçamento<\/a>/);assert.match(h.el('#main').innerHTML,/Item financeiro exclusivo/);assert.doesNotMatch(h.el('#main').innerHTML,/Atividade de planejamento exclusiva/);h.click({edit:'budgetItems',id:'a'});assert.match(h.el('#fields').innerHTML,/Preço unitário/);assert.doesNotMatch(h.el('#fields').innerHTML,/Início previsto|Dependências/);h.el('#editor').close();h.route('activities');assert.match(h.el('#main').innerHTML,/Atividade de planejamento exclusiva/);assert.doesNotMatch(h.el('#main').innerHTML,/Item financeiro exclusivo/);h.click({edit:'activities',id:'a'});assert.doesNotMatch(h.el('#fields').innerHTML,/Preço unitário|Valor total|Unitário de material/);h.el('#editor').close();h.click({action:'new:measurements'});assert.match(h.el('#fields').innerHTML,/Item financeiro exclusivo/);assert.doesNotMatch(h.el('#fields').innerHTML,/Atividade de planejamento exclusiva/);h.el('#editor').close();h.click({action:'new:costs'});assert.match(h.el('#fields').innerHTML,/Etapa financeira/);assert.doesNotMatch(h.el('#fields').innerHTML,/Etapa de planejamento/)});

