test('check na própria linha conclui e desfaz sem abrir formulário',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa'}],services:[{id:'a',project:'p',stage:'e',name:'Atividade',unit:'m³',quantity:10,executed:2,total:1000}]});h.route('activities');assert.match(h.el('#main').innerHTML,/data-action="activity-done:a" aria-pressed="false"/);let before=JSON.parse(h.local.get('engefex-gerenciamento-v2'));h.click({action:'activity-done:a'});let done=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(done.activities[0].executed,10);assert.equal(done.activities[0].actualFinish,h.context.Obras.today());assert.match(h.el('#main').innerHTML,/data-action="activity-done:a" aria-pressed="true"/);assert.equal(h.el('#editor').open,false);assert.equal(JSON.stringify(done.budgetItems),JSON.stringify(before.budgetItems));h.click({action:'activity-done:a'});let undo=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(undo.activities[0].executed,2);assert.equal(undo.activities[0].actualFinish,'');assert.match(h.el('#main').innerHTML,/aria-pressed="false"/)});

test('concluir e desfazer preservam rolagem vertical e horizontal após reconstruir a tabela',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa'}],services:[{id:'a',project:'p',stage:'e',name:'Atividade',quantity:10,executed:2,total:100}]});h.route('activities');let wrap={scrollLeft:280,scrollTop:90},html=h.el('#main').innerHTML,frames=[];h.context.scrollX=12;h.context.scrollY=1450;h.context.document.querySelectorAll=selector=>selector==='#main .table-wrap'?[wrap]:[];Object.defineProperty(h.el('#main'),'innerHTML',{get:()=>html,set:value=>{html=value;h.context.scrollY=0;h.context.scrollX=0;wrap.scrollLeft=0;wrap.scrollTop=0}});h.context.scrollTo=position=>{h.context.scrollX=position.left;h.context.scrollY=position.top};h.context.requestAnimationFrame=fn=>frames.push(fn);for(let n=0;n<2;n++){h.click({action:'activity-done:a'});assert.equal(h.context.scrollY,1450);assert.equal(h.context.scrollX,12);assert.equal(wrap.scrollLeft,280);assert.equal(wrap.scrollTop,90);h.context.scrollY=0;frames.shift()();assert.equal(h.context.scrollY,1450);assert.equal(wrap.scrollLeft,280)}assert.equal(JSON.parse(h.local.get('engefex-gerenciamento-v2')).activities[0].executed,2)});

test('listas cadastrais oferecem edição em planilha e grade salva colunas sem formulário',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],teams:[{id:'t',project:'p',name:'Equipe antiga',quantity:3}]});for(let route of ['projects','activities','budget','measurements','checklist','issues','teams','agenda']){h.route(route);if(route==='supplies')h.click({tab:'supplies',value:'materials'});assert.match(h.el('#main').innerHTML,/Editar em planilha/,route)}h.route('teams');let input={dataset:{recordRow:'0',recordKey:'name'},value:'Equipe alterada',tagName:'INPUT',events:{},addEventListener(n,fn){this.events[n]=fn}};h.context.document.getElementById=id=>h.el('#'+id);h.context.document.querySelectorAll=selector=>selector==='[data-record-row]'?[input]:[];h.click({action:'records-grid:teams'});assert.match(h.el('#main').innerHTML,/records-sheet/);assert.match(h.el('#main').innerHTML,/data-record-key="people"/);input.events.input();h.el('#recordsSave').onclick();let saved=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(saved.teams[0].name,'Equipe alterada');assert.equal(saved.teams[0].people,3);assert.equal(h.el('#editor').open,false);h.click({action:'records-close'});assert.match(h.el('#main').innerHTML,/Equipe alterada/)});

