test('menu separa obras, financeiro, fabricação e consulta Nextar na rota ativa',()=>{let h=harness();let nav=h.el('#nav').innerHTML,allGroups=Array.from(nav.matchAll(/<details[\s\S]*?<\/details>/g),m=>m[0]),groups=[allGroups.find(x=>x.includes('Gerenciamento de obras')),allGroups.find(x=>x.includes('Financeiro')),allGroups.find(x=>x.includes('Fabricação')),allGroups.find(x=>x.includes('Estoque Nextar'))];assert.equal(groups.filter(Boolean).length,4);assert.match(groups[3],/Estoque Nextar/);assert.match(groups[0],/Gerenciamento de obras/);for(let key of ['activities','timeline','budget','diary','checklist','issues','measurements'])assert.match(groups[0],new RegExp('href="#'+key+'"'));assert.doesNotMatch(groups[0],/href="#payables"|href="#receivables"/);assert.match(groups[1],/Financeiro/);assert.match(groups[1],/href="#payables"/);assert.doesNotMatch(groups[1],/href="#measurements"/);assert.match(groups[2],/Fabricação/);h.route('payables');assert.match(h.el('#nav').innerHTML,/<details class="nav-module is-active" open><summary><span>Financeiro/);assert.match(h.el('#main').innerHTML,/<h1>Contas a pagar<\/h1>/);assert.match(h.el('.breadcrumb').innerHTML,/Financeiro/);h.route('fabrication');assert.match(h.el('#main').innerHTML,/<h1>Fábrica<\/h1>/);assert.doesNotMatch(h.el('#main').innerHTML,/Importar planilha|Nova ordem/);assert.doesNotMatch(h.el('#main').innerHTML,/Em breve/);h.route('budget');assert.doesNotMatch(h.el('#main').innerHTML,/data-value="costs"/);h.route('measurements');assert.match(h.el('#main').innerHTML,/Medições e recebimentos/)});
