test('contas quitadas saem de Em aberto para Pagos e saldo reaberto retorna sem duplicar dados',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa'}],costs:[{id:'partial',project:'p',stage:'e',name:'Parcial exclusivo',amount:100,paid:30},{id:'paid',project:'p',stage:'e',name:'Quitado exclusivo',amount:100,paid:100},{id:'unpaid',project:'p',stage:'e',name:'Aberto exclusivo',amount:100,paid:0}]});h.route('payables');let html=()=>h.el('#main').innerHTML;assert.match(html(),/data-value="open" class="active"/);assert.match(html(),/Parcial exclusivo/);assert.match(html(),/Aberto exclusivo/);assert.doesNotMatch(html(),/Quitado exclusivo/);h.click({tab:'payables',value:'paid'});assert.match(html(),/Quitado exclusivo/);assert.doesNotMatch(html(),/Parcial exclusivo|Aberto exclusivo/);let s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));s.costs.find(c=>c.id==='partial').paid=100;s.costs.find(c=>c.id==='paid').paid=80;h.local.set('engefex-gerenciamento-v2',JSON.stringify(s));h.emit('storage',{key:'engefex-gerenciamento-v2'});assert.match(html(),/Parcial exclusivo/);assert.doesNotMatch(html(),/Quitado exclusivo/);h.click({tab:'payables',value:'open'});assert.match(html(),/Quitado exclusivo/);assert.match(html(),/Aberto exclusivo/);assert.doesNotMatch(html(),/Parcial exclusivo/);assert.equal(JSON.parse(h.local.get('engefex-gerenciamento-v2')).costs.length,3);});

test('botão Pagar confirma desconto ou acréscimo, impede duplo clique e mostra Pago verde',async()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra',client:'Cliente Azul'}],stages:[{id:'e',project:'p',name:'Etapa'}],costs:[{id:'c',project:'p',stage:'e',name:'Nota 123',supplier:'Fornecedor',amount:9,paid:0,incurred:0,date:'2026-10-20'}]});h.route('payables');assert.match(h.el('#main').innerHTML,/data-action="payment-toggle:c">Pagar/);assert.match(h.el('#main').innerHTML,/Nota \/ documento|Cliente da obra|Vencimento: de/);h.click({action:'payment:c'});assert.equal(h.el('#reader').open,true);assert.match(h.el('#readerContent').innerHTML,/Valor original|Valor pago agora|Pagamento parcial/);h.el('#paymentAmount').value='10';h.el('#paymentMode').value='settle';h.el('#paymentDate').value='2026-10-17';h.el('#paymentNote').value='Juros';h.el('#paymentAmount').oninput();assert.match(h.el('#paymentPreview').textContent,/Acréscimo deste pagamento/);let first=h.el('#paymentForm').onsubmit({preventDefault(){}}),second=h.el('#paymentForm').onsubmit({preventDefault(){}});await Promise.all([first,second]);let s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(s.costs[0].amount,9);assert.equal(s.costs[0].paid,10);assert.equal(s.costs[0].paymentAddition,1);assert.equal(s.history.filter(x=>x.action==='Pagamento registrado').length,1);assert.doesNotMatch(h.el('#main').innerHTML,/data-action="payment:c"/);h.click({tab:'payables',value:'paid'});assert.match(h.el('#main').innerHTML,/class="button payment-paid" data-action="payment-toggle:c">✓ Pago/);h.click({action:'payment:c'});assert.match(h.el('#readerContent').innerHTML,/Conta|✓ Pago/);assert.doesNotMatch(h.el('#readerContent').innerHTML,/id="paymentForm"/);});

