test('nova medição oferece somente orçamento da obra escolhida, com quantidade e valor, sem cronograma ou outra obra',()=>{let h=harness(),initial={version:1,dataModel:2,projects:[{id:'p',name:'Obra P'},{id:'q',name:'Obra Q'}],stages:[{id:'plan',project:'p',name:'Grupo do cronograma'}],activities:[{id:'task',project:'p',stage:'plan',name:'Atividade exclusiva do cronograma',quantity:100,executed:0}],budgetStages:[{id:'bp',project:'p',name:'Etapa orçada P'},{id:'bq',project:'q',name:'Etapa orçada Q'}],budgetItems:[{id:'itemp',project:'p',stage:'bp',code:'3.1',name:'Concreto financeiro P',quantity:12,unit:'m³',sale:1200},{id:'itemq',project:'q',stage:'bq',code:'4.1',name:'Concreto financeiro Q',quantity:8,unit:'m³',sale:800}]};let modern=JSON.parse(h.local.get('engefex-gerenciamento-v2'));Object.assign(modern,initial);for(let kind of ['stages','activities','budgetStages','budgetItems'])modern[kind]=modern[kind].map(r=>({...h.context.EngefexManager.defaults(kind,r.project),...r}));h.local.set('engefex-gerenciamento-v2',JSON.stringify(modern));h.emit('storage',{key:'engefex-gerenciamento-v2'});h.el('#project').onchange({target:{value:'p'}});h.click({action:'new:measurements'});let html=h.el('#fields').innerHTML;assert.match(html,/Item do orçamento/);assert.match(html,/Concreto financeiro P/);assert.match(html,/3.1/);assert.match(html,/12 m³/);assert.doesNotMatch(html,/Concreto financeiro Q|Atividade exclusiva do cronograma/);h.el('#editor').close();h.el('#project').onchange({target:{value:'q'}});h.click({action:'new:measurements'});html=h.el('#fields').innerHTML;assert.match(html,/Concreto financeiro Q/);assert.doesNotMatch(html,/Concreto financeiro P|Atividade exclusiva do cronograma/);});


test('medição em planilha carrega acumulados na próxima medição e impede duplo salvamento',async()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra'}],stages:[{id:'e',project:'p',name:'Etapa'}],services:[{id:'a',project:'p',stage:'e',name:'Item A',quantity:100,total:1000},{id:'b',project:'p',stage:'e',name:'Item B',quantity:200,total:2000}]});h.context.crypto=require('node:crypto').webcrypto;h.el('#project').onchange({target:{value:'p'}});h.route('measurements');assert.match(h.el('#main').innerHTML,/data-action="measurement-sheet"/);let cells=[{dataset:{msCurrent:'0'},value:'',disabled:false},{dataset:{msCurrent:'1'},value:'',disabled:false}];h.context.document.querySelectorAll=selector=>selector==='[data-ms-current]'?cells:[];h.click({action:'measurement-sheet'});assert.equal(h.el('#reader').open,true);assert.match(h.el('#readerContent').innerHTML,/Medido anteriormente|Acumulado atual|Nesta medição/);h.el('#measurementSheetNumber').value='01';h.el('#measurementSheetDate').value='2026-10-17';h.el('#measurementSheetNote').value='Conferir';cells[0].value='10';cells[0].oninput();cells[1].value='15';cells[1].oninput();const originalSelector=h.context.document.querySelector;h.context.document.querySelector=selector=>selector==='#measurementSheetType'?null:originalSelector(selector);assert.doesNotMatch(h.el('#readerContent').innerHTML,/id="measurementSheetType"/);let first=h.el('#measurementSheetForm').onsubmit({preventDefault(){}}),second=h.el('#measurementSheetForm').onsubmit({preventDefault(){}});await Promise.all([first,second]);let s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(s.measurements.length,2);assert.equal(s.measurements.find(m=>m.activity==='a').quantity,10);h.click({action:'measurement-sheet'});assert.match(h.el('#readerContent').innerHTML,/value="10"/);assert.match(h.el('#readerContent').innerHTML,/value="15"/);h.el('#measurementSheetNumber').value='02';h.el('#measurementSheetDate').value='2026-10-17';cells[0].value='25';cells[0].oninput();cells[1].value='20';cells[1].oninput();await h.el('#measurementSheetForm').onsubmit({preventDefault(){}});s=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(s.measurements.length,4);assert.equal(s.measurements.find(m=>m.number==='02'&&m.activity==='a').quantity,15);assert.equal(s.measurements.find(m=>m.number==='02'&&m.activity==='b').quantity,10);});

