test('compra abre rateio do mesmo item e permite destinos em obras diferentes sem salvar a prévia',()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra A'},{id:'q',name:'Obra B'}],stages:[{id:'e',project:'p',name:'Etapa A'},{id:'eq',project:'q',name:'Etapa B'}],services:[{id:'a',project:'p',stage:'e',name:'Aço orçamento A',quantity:100,total:1000},{id:'b',project:'q',stage:'eq',name:'Aço orçamento B',quantity:100,total:1000}]});h.context.crypto=require('node:crypto').webcrypto;h.el('#project').onchange({target:{value:'p'}});let split={dataset:{purchaseSplit:'0'}},controls=[{dataset:{purchaseAllocation:'0',key:'share'},value:'60'},{dataset:{purchaseAllocation:'1',key:'project'},value:'q'},{dataset:{purchaseAllocation:'1',key:'stage'},value:'eq'},{dataset:{purchaseAllocation:'1',key:'share'},value:'40'}];h.context.document.querySelectorAll=selector=>selector==='[data-purchase-split]'?[split]:selector==='[data-purchase-allocation]'?controls:[];h.click({action:'purchase-new'});assert.match(h.el('#readerContent').innerHTML,/Ratear item/);split.onclick();assert.match(h.el('#readerContent').innerHTML,/Rateio de item da compra/);h.el('#purchaseAddAllocation').onclick();for(let el of controls)el.onchange();let html=h.el('#readerContent').innerHTML;assert.match(html,/Rateado entre 2 destinos/);assert.match(html,/Etapa B/);assert.match(html,/value="60"/);assert.match(html,/value="40"/);assert.equal(JSON.parse(h.local.get('engefex-gerenciamento-v2')).purchases.length,0);h.el('#purchaseResetAllocation').onclick();assert.doesNotMatch(h.el('#readerContent').innerHTML,/Rateado entre 2 destinos/);});

test('contas a pagar separa parcelas e paga somente os destinos da parcela escolhida',async()=>{let h=harness({version:1,projects:[{id:'p',name:'Obra A'},{id:'q',name:'Obra B'}],stages:[{id:'e',project:'p',name:'Etapa A'},{id:'eq',project:'q',name:'Etapa B'}],services:[{id:'a',project:'p',stage:'e',name:'Aço A',quantity:100,total:1000},{id:'b',project:'q',stage:'eq',name:'Aço B',quantity:100,total:1000}]});h.context.crypto=require('node:crypto').webcrypto;let s=JSON.parse(h.local.get('engefex-gerenciamento-v2')),P=h.context.EngefexPurchases,p=P.fresh('p');Object.assign(p,{number:'NF-77',kind:'Nota fiscal',supplier:'Fornecedor Nota Única',status:'Confirmada',items:[{...P.newItem(),description:'Aço',quantity:1,unitPrice:1000,total:1000,budgetItem:'',allocations:[{project:'p',stage:'e',share:60},{project:'q',stage:'eq',share:40}]}],installments:[{id:'part1',number:'1',amount:500,due:'2026-10-20'},{id:'part2',number:'2',amount:500,due:'2026-11-20'}]});s=P.save(s,p);h.local.set('engefex-gerenciamento-v2',JSON.stringify(s));h.emit('storage',{key:'engefex-gerenciamento-v2'});h.el('#project').onchange({target:{value:'q'}});h.route('payables');let key='invoice:'+p.id+':part1';assert.match(h.el('#main').innerHTML,new RegExp('data-action="payable-detail:'+key+'"'));assert.match(h.el('#main').innerHTML,/NF-77/);assert.doesNotMatch(h.el('#main').innerHTML,/data-edit="costs"/);h.click({action:'payable-detail:'+key});assert.match(h.el('#readerContent').innerHTML,/Obra A/);assert.match(h.el('#readerContent').innerHTML,/Obra B/);assert.match(h.el('#readerContent').innerHTML,/Etapa A/);assert.match(h.el('#readerContent').innerHTML,/Etapa B/);h.click({action:'payment:'+key});assert.match(h.el('#readerContent').innerHTML,/Pagamento somente desta parcela/);h.el('#paymentAmount').value='490';h.el('#paymentMode').value='settle';h.el('#paymentDate').value='2026-10-17';h.el('#paymentNote').value='Desconto da nota';await h.el('#paymentForm').onsubmit({preventDefault(){}});let after=JSON.parse(h.local.get('engefex-gerenciamento-v2'));assert.equal(h.context.Obras.sum(after.costs,c=>c.paid),490);assert.equal(h.context.Obras.sum(after.costs,c=>c.paymentDiscount||0),10);assert.match(h.el('#main').innerHTML,/parcela 2\/2/);assert.doesNotMatch(h.el('#main').innerHTML,/parcela 1\/2/);h.click({tab:'payables',value:'paid'});assert.match(h.el('#main').innerHTML,/NF-77/);assert.equal(h.context.EngefexPayables.groups(after).length,2);});


