test('condições de retenção salvam online uma única vez e bloqueiam estado desatualizado',async()=>{let h=harness(),s=JSON.parse(h.local.get('engefex-gerenciamento-v2')),M=h.context.EngefexManager,D=h.context.Obras;s.projects=[{...M.defaults('projects'),id:'p',name:'Obra',value:1000}];s.budgetStages=[{...M.defaults('budgetStages','p'),id:'st',name:'Etapa'}];s.budgetItems=[{...M.defaults('budgetItems','p'),id:'a',stage:'st',name:'Serviço',quantity:100,sale:1000}];s=D.saveRecord(s,'measurements',{id:'m',project:'p',activity:'a',number:'01',quantity:100,date:'2026-10-17',status:'Preparada'});let current=D.clone(s),calls=0,resolve;h.context.EngefexRetentions.init({getState:()=>D.clone(current),save:next=>{calls++;current=next;return new Promise(r=>{resolve=r})},render:()=>{},toast:()=>{}});h.click({action:'retention-terms:m'});assert.equal(h.el('#reader').open,true);h.el('#retentionType').value='Medição';h.el('#retentionRate').value='5';h.el('#retentionReleased').checked=true;let submit=h.el('#retentionForm').onsubmit({preventDefault(){}});assert.equal(h.context.EngefexRetentions.busy(),true);await h.el('#retentionForm').onsubmit({preventDefault(){}});assert.equal(calls,1);resolve(true);await submit;assert.equal(h.el('#reader').open,false);assert.equal(current.measurements[0].retentionReleased,true);h.click({action:'retention-terms:m'});current.projects[0].name='Outro nome';await h.el('#retentionForm').onsubmit({preventDefault(){}});assert.match(h.el('#retentionError').textContent,/dados mudaram/);assert.equal(calls,1);});


